12	 public OrderSuggestion suggestion(){LocalDateTime now=LocalDateTime.now(clock);LocalTime t=now.toLocalTime();if(t.isBefore(LocalTime.of(10,0)))return new OrderSuggestion(now.toLocalDate().toString(),"LUNCH");if(t.isBefore(LocalTime.of(15,0)))return new OrderSuggestion(now.toLocalDate().toString(),"DINNER");return new OrderSuggestion(now.toLocalDate().plusDays(1).toString(),"LUNCH");}
