+  assertEquals(1,outcomes.stream().filter(Outcome::succeeded).count(),outcomes.toString());
+  assertEquals(1,count("select count(*) from orders"));
+  assertEquals(1,stock(fixture.dishIds().get(0)));
+ }
+
+ @Test
