+  assertEquals(2,stock(fixture.dishIds().get(0)));
+  assertEquals(0,stock(fixture.dishIds().get(1)));
+  assertEquals(0,count("select count(*) from orders"));
+ }
+
+ @Test
+ void concurrent_repeat_cancellation_restores_stock_once(){
